.assistant-page{display:flex;flex-direction:column;height:100%;min-height:0;min-width:0;box-sizing:border-box;overflow:auto;padding:22px 28px 18px;gap:14px;color:#1d2939;background:#f5f7fa}.chat-toolbar{display:flex;justify-content:space-between;gap:12px;align-items:center;flex:none}.chat-toolbar h2{margin:0 0 6px;font-size:21px}.chat-toolbar p{margin:0;color:#667085;font-size:13px;line-height:1.7}.toolbar-actions{display:flex;gap:8px;flex:none}.toolbar-actions .el-button{margin:0}.context-chip{display:flex;align-items:center;justify-content:space-between;gap:8px;background:#eaf4ef;border-radius:8px;padding:3px 12px;font-size:12px;color:#25624d;flex:none}.context-chip span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.assistant-messages{flex:1;min-height:160px;overflow:auto;padding:4px 4px 12px}.assistant-welcome{text-align:center;padding:10vh 12px;color:#667085}.welcome-symbol{font-size:32px;color:#3370ff}.assistant-welcome h3{font-size:21px;color:#344054}.assistant-welcome p{font-size:14px;line-height:1.8}.question-examples{display:flex;justify-content:center;gap:8px;flex-wrap:wrap;margin-top:24px}.question-examples .el-button{margin:0}.assistant-turn{margin-bottom:24px}.question-bubble{margin:0 0 12px auto;max-width:78%;width:fit-content;background:#eaf1ff;border:1px solid #dbe6ff;border-radius:12px;padding:12px 16px}.question-bubble span{font-size:11px;color:#667085}.question-bubble p{margin:5px 0 0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.8}.answer-bubble{background:white;border:1px solid #e4e7ec;border-radius:12px;padding:16px;overflow:hidden}.answer-meta{display:flex;gap:12px;align-items:center;font-size:13px}.answer-meta span,.assistant-hint{font-size:12px;color:#667085;line-height:1.8}.assistant-answer-text{white-space:pre-wrap;font-size:14px;line-height:1.9;overflow-wrap:anywhere}.turn-warning{color:#8b641a;background:#fff8e8;border-radius:6px;padding:9px;font-size:12px;line-height:1.8}.survey-results article{border-top:1px solid #edf0f4;padding:12px 0;display:flex;align-items:center;justify-content:space-between;gap:12px}.survey-results strong{font-size:14px;overflow-wrap:anywhere}.survey-results p{font-size:12px;color:#667085;margin:5px 0}.stat-count{font-size:15px;font-weight:600;margin:14px 0}.option-stat-question{font-size:12px;border-bottom:1px solid #f0f1f4;padding:8px 0;line-height:1.8}.retrieval-scope,.report-result{font-size:13px;line-height:1.9;overflow-wrap:anywhere}.citation-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}.citation-actions .el-button{margin:0}.result-footer{display:flex;justify-content:space-between;gap:8px;align-items:center;flex-wrap:wrap;color:#667085;font-size:11px;margin-top:12px}.assistant-composer{border:1px solid #dfe5ed;border-radius:12px;padding:12px;background:white;flex:none}.composer-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:9px}.composer-footer span{font-size:11px;color:#667085;line-height:1.7}.assistant-error{flex:none}.assistant-citation{line-height:1.8;overflow-wrap:anywhere}.assistant-citation blockquote{white-space:pre-wrap;background:#f5f7fa;border-left:3px solid #3370ff;padding:14px;margin:16px 0}.conversation-list{display:flex;flex-direction:column;gap:8px}.conversation-list .el-button{justify-content:flex-start;white-space:normal;line-height:1.8;height:auto;text-align:left;margin:0}
@media(max-width:700px){.assistant-page{padding:14px 12px 10px;gap:10px}.chat-toolbar{align-items:flex-start}.chat-toolbar h2{font-size:17px}.chat-toolbar p{font-size:12px}.toolbar-actions{gap:2px}.toolbar-actions .el-button{padding:8px}.assistant-welcome{padding:5vh 8px}.assistant-welcome h3{font-size:19px}.answer-bubble{padding:12px}.assistant-composer{position:sticky;bottom:0;z-index:2;padding:10px}.composer-footer{align-items:flex-end;gap:8px}.composer-footer span{font-size:10px}.question-bubble{max-width:85%}}
</style>
